import sys

class Vert:
    def __init__(self,i,lastMask) -> None:
        self.i = i
        self.links = []
        self.indexMask = 1 << i
        self.lastMask = lastMask

    def link(self,next):
        self.links.append(next)
        next.links.append(self)

    def count(self,mask):
        if mask & self.indexMask > 0:
            return 0
        nextMask = mask | self.indexMask
        if self.lastMask == nextMask:
            return 1
        result = 0
        for l in self.links:
            result += l.count(nextMask)
        return result

def solve(N: int, M: int, a: "List[int]", b: "List[int]"):
    lastMask = (1 << N) - 1
    V = [Vert(i,lastMask) for i in range(N)]
    for i in range(M):
        V[a[i]-1].link(V[b[i]-1])
    print(V[0].count(0))
    return


