from typing import List

def check(a: List[int], is_neg: bool):
    cumsum = res = 0
    for x in a:
        cumsum += x
        if is_neg is not (cumsum < 0) or not cumsum:
            res += abs(cumsum) + 1
            cumsum = -1 if is_neg else 1
        is_neg = not is_neg

    return res

