import sys

MOD = 1000000007  # type: int


def solve(N: int, M: int):
    from functools import reduce
    if abs(N - M) > 1:
        return 0
    n = reduce(lambda a,b:a*b%MOD, range(1, N+1))
    m = reduce(lambda a,b:a*b%MOD, range(1, M+1))
    if N == M:
        return n * m * 2 % MOD
    return n * m % MOD

