def bellman_ford(edge, start, end=None):
    INF = -(10**15)
    d = [INF] * len(edge)
    d[start] = 0

    for i in range(len(edge) * 2):
        updated = False

        for fr, ed in enumerate(edge):
            for to, cost in ed:
                if d[fr] != INF and d[to] < d[fr] + cost:
                    d[to] = d[fr] + cost
                    updated = True

                    # Found positive cycle
                    if i == len(edge) * 2 - 1 and to == end:
                        return -1

        if not updated:
            break

    if end is not None:
        return d[end]
    else:
        return d


