# ABC061 D - Score Attack
# https://atcoder.jp/contests/abc061/tasks/abc061_d

def BellmanFord(vi, N, e_list, neg = True):
    min_d_list = [float("inf")]*N
    min_d_list[vi] = 0
    prev_list = [None]*N

    for i in range(N-1):
        for u,v,d in e_list:
            if min_d_list[v] > min_d_list[u]+d:
                min_d_list[v] = min_d_list[u]+d
                prev_list[v] = u
    if neg:
        neg_loop_flag = [False]*N
        for i in range(N):
            for u,v,d in e_list:
                if min_d_list[u] + d < min_d_list[v]:
                    neg_loop_flag[v] = True
                    min_d_list[v] = min_d_list[u] + d
                if neg_loop_flag[u]:
                    neg_loop_flag[v] = True
    else:
        neg_loop_flag = None

    return min_d_list, prev_list, neg_loop_flag

