    def __init__(self, n):
        self.parents = [-1] * n

    def root(self, x):
        y = self.parents[x]
        if y < 0: return x
        else: return self.root(y)

    def find(self, x, y):
        return self.root(x) == self.root(y)

    def unite(self, x, y):
        r1 = self.root(x)
        r2 = self.root(y)
        if r1 == r2: return 0
        p1 = self.parents[r1]
        p2 = self.parents[r2]
        if p1 <= p2:
            self.parents[r2] = r1
            self.parents[r1] += p2
        else:
            self.parents[r1] = r2
            self.parents[r2] += p1
        return -p1-p2

