        self._sizes = [1 for _ in range(n)]

    def root(self, x):
        if self._parents[x] == -1:
            return x
        self._parents[x] = self.root(self._parents[x])
        return self._parents[x]

    def unite(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if x == y:
